function registerWsHandlers() {
    const w = window.__app.wsManager;
    // 后端广播为顶层字段：{type, pos, quat, vel, ...}（无 payload 键），
    // _dispatch 已统一为 payload ?? data，此处 handler 直接收顶层对象。
