    });
    w.on('link_status', p => {
        if (!p || !p.link) return;
        const state = p.state || 'unknown';
        store.batch(() => {
            if (p.link === 'A-B') {
                store.set('connection.backendA', state);
                store.set('connection.backendB', state);
            } else if (p.link === 'llm') {
                store.set('connection.llm', state);
            }
        });
    });
