/**
 * FlightPlanCard — Structured card showing a flight plan with ActionCommand actions.
 * schema_version=2: uses actions format (not legacy segments/waypoints).
 */

import { esc } from '../escape.js';

class FlightPlanCard {
    /**
     * @param {object} plan
